process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const A=Buffer.from('','base64').toString();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'m', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function main(){
  const out={};
  fs.writeFileSync('/tmp/k.html', A);
  const br=await chromium.launch();
  const p=await (await br.newContext({viewport:{width:1400,height:1300}})).newPage();
  const kl=[]; p.on('pageerror',e=>kl.push(String(e).slice(0,130)));
  await p.goto('file:///tmp/k.html',{waitUntil:'networkidle'});
  await p.waitForTimeout(700);
  out.skirtukai=await p.locator('.tabs button').allInnerTexts();
  /* aprasymai — ar serimo lentele ten */
  await p.click('.tabs button[data-t="apr"]'); await p.waitForTimeout(600);
  out.aprasymuose_serimas=await p.locator('.pane[data-p="apr"]').innerText().then(t=>t.includes('Šėrimo lentelė'));
  await p.screenshot({path:'/tmp/k_apr.png',fullPage:true});
  /* pakuotes skirtukas */
  await p.click('.tabs button[data-t="pak"]'); await p.waitForTimeout(600);
  out.pakuotes_matoma=await p.locator('.pane[data-p="pak"]').isVisible();
  out.pakuotes_turinys=await p.locator('.pane[data-p="pak"] .blk-antr').allInnerTexts();
  await p.screenshot({path:'/tmp/k_pak.png',fullPage:true});
  /* apzvalga — ar serimo/gpais tikrai dingo */
  await p.click('.tabs button[data-t="apz"]'); await p.waitForTimeout(500);
  const apz=await p.locator('.pane[data-p="apz"]').innerText();
  out.apzvalgoje_liko_serimas=apz.includes('Šėrimo lentelė');
  out.apzvalgoje_liko_gpais=apz.includes('GPAIS');
  out.js_klaidos=kl;
  await br.close();
  for(const f of ['k_apr','k_pak']){ try{ await put('screenshots/'+f+'.png', fs.readFileSync('/tmp/'+f+'.png'), f); }catch(e){} }
  await put('analize/kort2.json', Buffer.from(JSON.stringify(out,null,2)),'k');
}
main().catch(async e=>{ await put('analize/kort2.json',Buffer.from(JSON.stringify({klaida:String(e)})),'err'); });
